<?php

declare(strict_types=1);

namespace App\Http\Controllers\Auth;

use Sahil\Auth\PasswordResetManager;
use Sahil\Contracts\Foundation\ApplicationContract;
use Sahil\Contracts\Mail\MailerContract;
use Sahil\Contracts\View\ViewContract;
use Sahil\Http\Request;
use Sahil\Http\Response;
use Sahil\Mail\Message;
use Sahil\Validation\ValidationResult;
use Sahil\Validation\Validator;
use Throwable;

/**
 * Password reset link endpoint generated by `php sahil unda:auth`.
 *
 * The response is always neutral: it never reveals whether an address is
 * registered. Links are single-use and expire after the configured window.
 */
final class ForgotPasswordController
{
    public function __construct(
        private readonly ViewContract $views,
        private readonly ApplicationContract $application,
        private readonly PasswordResetManager $reset,
        private readonly MailerContract $mail,
    ) {
    }

    public function showLinkRequestForm(): Response
    {
        return $this->page('auth.forgot-password');
    }

    public function sendResetLinkEmail(Request $request): Response
    {
        $form = $request->form();
        $email = $this->email($form);

        $result = $this->validator([
            'email' => 'required|email|length:3,190',
        ], [
            'email.required' => 'Enter the email address for your account.',
            'email.email' => 'Enter a valid email address, like you@example.com.',
            'email.length' => 'That email address is too long.',
        ])->validate([...$form, 'email' => $email]);

        if ($result->fails()) {
            return $this->formPage('auth.forgot-password', $result, $form);
        }

        $token = $this->reset->createToken($email);

        if ($token !== null) {
            try {
                $this->sendResetMail($request, $email, $token);
            } catch (Throwable) {
                return $this->formPage('auth.forgot-password', $result, $form, null, [
                    'email' => 'We could not send the reset email right now. Please try again.',
                ]);
            }
        }

        return $this->formPage(
            'auth.forgot-password',
            $result,
            $form,
            sprintf('If an account exists for %s, a password reset link is on its way.', $email),
        );
    }

    /**
     * Mail the single-use reset link. `PasswordResetManager` has already
     * stored the token; the plaintext value exists only in this URL.
     */
    private function sendResetMail(Request $request, string $email, string $token): void
    {
        $scheme = $request->scheme() ?? 'http';
        $host = $request->header('Host') ?? 'localhost';
        $url = sprintf('%s://%s/reset-password/%s', $scheme, $host, rawurlencode($token));
        $minutes = (int) $this->application->config()->get('auth.password_reset.token_expiration', 60);

        $this->mail->send(
            Message::make()
                ->to($email)
                ->subject('Reset your '.$this->application->config()->get('app.name', 'SahilPHP').' password')
                ->text(implode("\n", [
                    'We received a request to reset the password for this address.',
                    '',
                    'Open this link to choose a new password:',
                    $url,
                    '',
                    sprintf('The link expires in %d minutes and can be used once.', $minutes),
                    'If you did not request a reset, no action is needed.',
                ])),
        );
    }

    /**
     * @param array<string, string|array<int, string|\Closure>> $rules
     * @param array<string, string> $messages
     */
    private function validator(array $rules, array $messages): Validator
    {
        return new Validator($rules, $messages);
    }

    /**
     * @param array<string, string> $form
     * @param array<string, string> $errors
     */
    private function formPage(
        string $view,
        ?ValidationResult $result = null,
        array $form = [],
        ?string $status = null,
        array $errors = [],
    ): Response {
        $messages = [];

        foreach ($result?->errors() ?? [] as $field => $list) {
            $messages[$field] = $list[0] ?? '';
        }

        return $this->page($view, [
            'errors' => [...$messages, ...$errors],
            'old' => [
                'email' => $this->oldString($form, 'email'),
            ],
            'status' => $status,
        ]);
    }

    /**
     * @param array<string, mixed> $form
     */
    private function oldString(array $form, string $key): string
    {
        $value = $form[$key] ?? '';

        return is_string($value) ? $value : '';
    }

    /**
     * @param array<string, mixed> $form
     */
    private function email(array $form): string
    {
        return strtolower(trim($this->oldString($form, 'email')));
    }

    /**
     * @param array<string, mixed> $data
     */
    private function page(string $view, array $data = []): Response
    {
        return Response::html($this->views->render($view, [
            'app_name' => (string) $this->application->config()->get('app.name', 'SahilPHP'),
            'year' => gmdate('Y'),
            'csrf_token' => csrf_token(),
            ...$data,
        ]));
    }
}
